class TariffService:
    @staticmethod
    def get_tariff(code: str) -> Optional[TariffItem]:
        return TARIFF_DATABASE.get(code.strip())

    @staticmethod
    def calculate_bill_total(service_codes: List[str], is_insured: bool = False) -> int:
        total = 0
        for c in service_codes:
            item = TARIFF_DATABASE.get(c)
            if item:
                total += item.insurance_rate_cents if is_insured else item.standard_rate_cents
        return total
